function bestProfitKTrades(k: number, prices: number[]): number {
  const n = prices.length;
  const best: number[][] = Array.from({ length: k + 1 }, () => new Array(n).fill(0));
  for (let t = 1; t <= k; t++) {
    for (let i = 1; i < n; i++) {
      let v = best[t][i - 1]; // day i is not a sell day
      for (let j = 0; j < i; j++) {
        v = Math.max(v, best[t - 1][j] + prices[i] - prices[j]); // buy on j, sell on i
      }
      best[t][i] = v;
    }
  }
  return best[k][n - 1];
}

