function bestProfitKTrades(k: number, prices: number[]): number {
  const n = prices.length;
  if (2 * k >= n) {
    // the cap never binds: take every rise
    let sum = 0;
    for (let i = 1; i < n; i++) sum += Math.max(0, prices[i] - prices[i - 1]);
    return sum;
  }
  const hold = new Array(k + 1).fill(-Infinity);
  const free = new Array(k + 1).fill(0);
  for (const p of prices) {
    for (let t = 1; t <= k; t++) {
      hold[t] = Math.max(hold[t], free[t - 1] - p);
      free[t] = Math.max(free[t], hold[t] + p);
    }
  }
  return free[k];
}

